        cgst = (self.amount * half_rate / Decimal("100.0")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        sgst = (self.amount * half_rate / Decimal("100.0")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        total = self.amount + cgst + sgst
