@dataclass
class KdsExpediterKanbanEntity40:
    """Data transfer object for KDS Station Kanban with Color-Coded SLA Timers - Segment 40."""
    entity_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    restaurant_code: str = "REST-IND-001"
